def chunk(words, max_words=20, overlap=5):
    out = []
    for start in range(0, len(words), max_words - overlap):
        out.append(words[start:start + max_words])
        if start + max_words >= len(words):
            break
    return out

print([len(c) for c in chunk(["w"] * 70)])

WEATHER_C = {"Paris": 18, "Oslo": 4, "Lima": 21}

def get_weather(city, unit="celsius"):
    c = WEATHER_C.get(city)
    if c is None:
        raise ValueError(f"no data for {city}")
    return f"{c} C" if unit == "celsius" else f"{c * 9 / 5 + 32:.0f} F"

print(get_weather("Oslo", unit="fahrenheit"))

