import json
lines = ['{"jsonrpc": "2.0", "method": "notifications/initialized"}',
         '{"jsonrpc": "2.0", "id": 1, "method": "tools/list"}', "not json"]
replies = []
for line in lines:
    try:
        msg = json.loads(line)
    except json.JSONDecodeError:
        replies.append({"id": None, "error": {"code": -32700}})
        continue
    if "id" in msg:
        replies.append({"id": msg["id"], "result": {}})
print(len(replies), "replies")

import re
SECRET = re.compile(r"sk-[A-Za-z0-9-]{8,}")

def redact(text):
    return SECRET.sub("[REDACTED]", text)

print(redact("The staging key is sk-test-51abcdef."))

RISKY = {"send_email"}
approve = lambda name, args: True

def execute(name, args):
    if name in RISKY and not (args["to"].endswith("@example.com") and approve(name, args)):
        return "error: denied (needs approval and an @example.com recipient)"
    return f"sent to {args['to']}"

